/**
 * Resolve the real client IP, taking reverse proxies into account.
 */
export function getClientIp(req) {
  const forwarded = req.headers['x-forwarded-for'];
  const raw = Array.isArray(forwarded) ? forwarded[0] : forwarded || req.ip;

  if (!raw) return 'unknown';

  return String(raw).split(',')[0].trim().slice(0, 64) || 'unknown';
}

/**
 * Device fingerprints are generated by the browser and persisted locally.
 * A missing fingerprint is returned as null so the server does not compare
 * shared user-agent strings and flag every student on the same browser build.
 */
export function getDeviceInfo(req) {
  const value = req.body?.deviceInfo;
  if (typeof value !== 'string') return null;

  const trimmed = value.trim().slice(0, 200);
  return trimmed.length > 0 ? trimmed : null;
}
